DEV void qk_half(float s[8][4], const bf16* ktile, const uint32_t qa[8][4], int nbase, int lane) {
  const int row = (lane & 7) + ((lane >> 4) & 1) * 8;
  const int col = ((lane >> 3) & 1) * 8;

#pragma unroll
  for (int t = 0; t < 8; ++t) {
#pragma unroll
    for (int i = 0; i < 4; ++i) s[t][i] = 0.f;
