    const int key = nbase + 8 * t + col;
    s[t][0] = (key <= qlo) ? s[t][0] : NEG_INF;
    s[t][1] = (key + 1 <= qlo) ? s[t][1] : NEG_INF;
    s[t][2] = (key <= qhi) ? s[t][2] : NEG_INF;
    s[t][3] = (key + 1 <= qhi) ? s[t][3] : NEG_INF;
