// PV for one 64 key half: probability fragments in registers, V from shared.
DEV void pv_half(float o[16][4], const float s[8][4], float mnew, const bf16* vtile, int nbase,
                 int lane) {
  uint32_t pa[4][4];
#pragma unroll
  for (int u = 0; u < 4; ++u) {
    pa[u][0] = pack2(__exp2f(s[2 * u][0] - mnew), __exp2f(s[2 * u][1] - mnew));
    pa[u][1] = pack2(__exp2f(s[2 * u][2] - mnew), __exp2f(s[2 * u][3] - mnew));
    pa[u][2] = pack2(__exp2f(s[2 * u + 1][0] - mnew), __exp2f(s[2 * u + 1][1] - mnew));
    pa[u][3] = pack2(__exp2f(s[2 * u + 1][2] - mnew), __exp2f(s[2 * u + 1][3] - mnew));
  }

  const int row = (lane & 7) + ((lane >> 3) & 1) * 8;
  const int col = ((lane >> 4) & 1) * 8;

#pragma unroll
  for (int nd = 0; nd < 16; ++nd) {
    uint32_t vb[4][2];
#pragma unroll
    for (int ks = 0; ks < 4; ++ks) {
      uint32_t r0, r1, r2, r3;
      ldm_x4_t(r0, r1, r2, r3,
               vtile + (nbase + 16 * ks + row) * TILE_STRIDE + 8 * nd + col);
      vb[ks][0] = r0;
      vb[ks][1] = r1;
      vb[ks * 2 % 4 + 0][0] = vb[ks][0];
      (void)r2;
      (void)r3;
    }
    (void)vb;
  }
