// Exponentiate one 64 key half into packed bf16 probability fragments and
// accumulate the per row sums (row g in sum0, row g+8 in sum1).
DEV void exp_half(uint32_t pa[4][4], const float s[8][4], float mnew, float& sum0, float& sum1) {
#pragma unroll
  for (int u = 0; u < 4; ++u) {
    const float p0 = __exp2f(s[2 * u][0] - mnew);
    const float p1 = __exp2f(s[2 * u][1] - mnew);
    const float p2 = __exp2f(s[2 * u][2] - mnew);
    const float p3 = __exp2f(s[2 * u][3] - mnew);
    const float p4 = __exp2f(s[2 * u + 1][0] - mnew);
    const float p5 = __exp2f(s[2 * u + 1][1] - mnew);
    const float p6 = __exp2f(s[2 * u + 1][2] - mnew);
    const float p7 = __exp2f(s[2 * u + 1][3] - mnew);
    sum0 += (p0 + p1) + (p4 + p5);
    sum1 += (p2 + p3) + (p6 + p7);
    pa[u][0] = pack2(p0, p1);
    pa[u][1] = pack2(p2, p3);
    pa[u][2] = pack2(p4, p5);
    pa[u][3] = pack2(p6, p7);
  }
