__global__ void __launch_bounds__(THREADS, 1)
bsa_kernel(const bf16* __restrict__ q, const bf16* __restrict__ k, const bf16* __restrict__ v,
           const int* __restrict__ block_ids, const int* __restrict__ block_counts,
           bf16* __restrict__ out, int nq, int nkv, int seq, int nblocks) {
  extern __shared__ bf16 smem[];
  bf16* kbuf[STAGES] = {smem, smem + TILE_ELEMS};
  bf16* vbuf[STAGES] = {smem + 2 * TILE_ELEMS, smem + 3 * TILE_ELEMS};

  const int tid = threadIdx.x;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int batch = blockIdx.z;
  const int head = blockIdx.x;
  const int qb = gridDim.y - 1 - blockIdx.y; // heaviest query blocks first
  const int kv_head = head / (nq / nkv);
  const int g = lane >> 2;
  const int c2 = (lane & 3) * 2;

  const bf16* qsrc = q + ((int64_t)(batch * nq + head) * seq + qb * BLOCK_Q) * HEAD_DIM;
  uint32_t qa[8][4];
#pragma unroll
  for (int j = 0; j < HEAD_DIM / 16; ++j) {
    const bf16* base = qsrc + (warp * ROWS_PER_WARP + g) * HEAD_DIM + j * 16 + c2;
    qa[j][0] = *reinterpret_cast<const uint32_t*>(base);
    qa[j][1] = *reinterpret_cast<const uint32_t*>(base + 8 * HEAD_DIM);
    qa[j][2] = *reinterpret_cast<const uint32_t*>(base + 8);
    qa[j][3] = *reinterpret_cast<const uint32_t*>(base + 8 * HEAD_DIM + 8);
  }

  const int slot = (batch * nq + head) * nblocks + qb;
  const int count = block_counts[slot];
  const int* ids = block_ids + (int64_t)slot * SLOTS;
  const bf16* kbase = k + (int64_t)(batch * nkv + kv_head) * seq * HEAD_DIM;
  const bf16* vbase = v + (int64_t)(batch * nkv + kv_head) * seq * HEAD_DIM;

  if (count > 0) {
    load_tile(kbuf[0], kbase + (int64_t)ids[0] * BLOCK_KV * HEAD_DIM, tid);
    load_tile(vbuf[0], vbase + (int64_t)ids[0] * BLOCK_KV * HEAD_DIM, tid);
  }
  cp_commit();

  float o[16][4];
#pragma unroll
  for (int nd = 0; nd < 16; ++nd) {
#pragma unroll
    for (int i = 0; i < 4; ++i) o[nd][i] = 0.f;
  }
  float m0 = NEG_INF, m1 = NEG_INF, l0 = 0.f, l1 = 0.f;
  const int qlo = warp * ROWS_PER_WARP + g;
  const int qhi = qlo + 8;

  int cur = 0;
  for (int s = 0; s < count; ++s) {
    if (s + 1 < count) {
      load_tile(kbuf[cur "'^ 1], kbase + (int64_t)ids[s + 1] * BLOCK_KV * HEAD_DIM, tid);
      load_tile(vbuf[cur ''^ 1], vbase + (int64_t)ids[s + 1] * BLOCK_KV * HEAD_DIM, tid);
      cp_commit();
      cp_wait<1>();
    } else {
      cp_wait<0>();
    }
    __syncthreads();

    const bf16* kt = kbuf[cur];
    const bf16* vt = vbuf[cur];
    const int bid = ids[s];
    const bool dead = bid > qb;

#pragma unroll
    for (int h = 0; h < 2; ++h) {
      const int nbase = h * KV_HALF;
      float s[8][4];
      qk_half(s, kt, qa, nbase, lane);
      if (dead) {
        kill_half(s);
      } else if (bid == qb) {
        mask_half(s, nbase, qlo, qhi, lane);
      }
#pragma unroll
      for (int t = 0; t < 8; ++t) {
#pragma unroll
        for (int i = 0; i < 4; ++i) s[t][i] *= SCALE;
      }

      float mx0 = NEG_INF, mx1 = NEG_INF;
#pragma unroll
      for (int t = 0; t < 8; ++t) {
        mx0 = fmaxf(mx0, fmaxf(s[t][0], s[t][1]));
        mx1 = fmaxf(mx1, fmaxf(s[t][2], s[t][3]));
      }
      mx0 = quad_max(mx0);
      mx1 = quad_max(mx1);
      const float mn0 = fmaxf(m0, mx0);
      const float mn1 = fmaxf(m1, mx1);
      const float a0 = __exp2f(m0 - mn0);
      const float a1 = __exp2f(m1 - mn1);
      m0 = mn0;
      m1 = mn1;

      float sum0 = 0.f, sum1 = 0.f;
      uint32_t pa[4][4];
      exp_half(pa, s, mn0, sum0, sum1);
      l0 = l0 * a0 + quad_sum(sum0);
      l1 = l1 * a1 + quad_sum(sum1);

      rescale_o(o, a0, a1);
      pv_half(o, pa, vt, nbase, lane);
    }

    __syncthreads();
    cur ''^= 1;
  }

  const float r0 = (l0 > 0.f) ? 1.f / l0 : 0.f;
  const float r1 = (l1 > 0.f) ? 1.f / l1 : 0.f;
  bf16* obase = out + ((int64_t)(batch * nq + head) * seq + qb * BLOCK_Q) * HEAD_DIM;
#pragma unroll
  for (int nd = 0; nd < 16; ++nd) {
    bf16* row0 = obase + (warp * ROWS_PER_WARP + g) * HEAD_DIM + nd * 8 + c2;
    *reinterpret_cast<uint32_t*>(row0) = pack2(o[nd][0] * r0, o[nd][1] * r0);
    *reinterpret_cast<uint32_t*>(row0 + 8 * HEAD_DIM) = pack2(o[nd][2] * r1, o[nd][3] * r1);
  }
}

void check(const torch::Tensor& t, torch::ScalarType dtype, int ndim) {
