  TORCH_CHECK_TYPE(t.scalar_type() == dtype, "Unexpected dtype");
  TORCH_CHECK_VALUE(t.dim() == ndim, "Unexpected rank");
  TORCH_CHECK_VALUE(t.is_contiguous(), "Expected contiguous tensor");
