#: Serialize temporary module/environment changes within this process.
IMPORT_LOCK = threading.RLock()
#: Mutable source staging directory used by compilers.
BUILD_SOURCES = "sources"
#: File lock covering source staging and compilation across processes.
BUILD_LOCK = ".klineage-build.lock"


@contextmanager
def source_import_scope(root: Path, modules: dict[str, ModuleType]):
    """Prevent ordinary local imports from leaking between two artifacts."""

    with IMPORT_LOCK:
        local_names = local_top_level_names(root)
        displaced = {
            name: module
            for name, module in tuple(sys.modules.items())
            if name in modules or name.split(".", 1)[0] in local_names
        }
        for name in displaced:
            sys.modules.pop(name, None)
        before = set(sys.modules)
        previous = sys.dont_write_bytecode
        sys.dont_write_bytecode = True
        sys.modules.update(modules)
        sys.path.insert(0, str(root))
        try:
            yield
        finally:
            sys.dont_write_bytecode = previous
            try:
                sys.path.remove(str(root))
            except ValueError:
                pass
            for name in set(sys.modules) - before:
                module = sys.modules.get(name)
                if module_is_under(module, root):
                    modules[name] = module
                    sys.modules.pop(name, None)
            sys.modules.update(displaced)


def local_top_level_names(root: Path) -> set[str]:
    names = {path.stem for path in root.glob("*.py") if path.name != "__init__.py"}
    # Directories without __init__.py are importable namespace packages too.
    names.update(path.name for path in root.iterdir() if path.is_dir())
    return names


def module_is_under(module: ModuleType | None, root: Path) -> TypeGuard[ModuleType]:
    if module is None:
        return False
    filename = getattr(module, "__file__", None)
    locations = (filename,) if filename else getattr(module, "__path__", ())
    try:
        return any(Path(path).resolve().is_relative_to(root) for path in locations)
    except (OSError, RuntimeError, ValueError):
        return False


class BundleLoader:
    def __init__(self, build_root: Path, *, include_paths: Sequence[Path] = ()):
        self.build_root = Path(build_root).resolve()
        self.include_paths = tuple(Path(path).resolve() for path in include_paths)
        self.modules: dict[str, Any] = {}

    def build(
        self,
        kernel: Kernel,
        *,
        strides: Mapping[tuple[str, str], tuple[int, ...]] | None = None,
    ) -> Callable[..., Any]:
        function = self.load(kernel)
        if (
            kernel.language == "python"
            and kernel.output_style is OutputStyle.RETURN
            and strides is None
        ):
            return function
        return BundleCallable(kernel.problem, function, kernel.output_style, strides)

    def load(self, kernel: Kernel) -> Callable[..., Any]:
        if BUNDLE_CONFIG in kernel.source_files and kernel.language == "python":
            backend = platform_backend(kernel.problem.platform)
            if backend is not None:
                backend.prepare()
            root = Path(snapshot(self.build_root, kernel.source_files))
            return self.load_python(root, kernel)

        backend = get_backend(kernel.problem.language, kernel.problem.platform)
        if BUNDLE_CONFIG not in kernel.source_files:
            if set(kernel.source_files) != {backend.raw_source}:
                raise ValueError(
                    f"raw {backend.kind} adapters require a single {backend.raw_source} source"
                )
            sources = {
                backend.raw_source: kernel.source_files[backend.raw_source],
                "binding.cpp": backend.binding(),
            }
            native_root = Path(snapshot(self.build_root, sources))
            module = self.load_native(
                native_root, sources, backend, kernel.compile_flags
            )
            launch = getattr(module, "launch", None)
            if not callable(launch):
                raise TypeError("native extension did not expose launch")
            input_count = len(kernel.problem.values(ValueRole.INPUTS))

            def run(*tensors):
                launch(list(tensors[:input_count]), list(tensors[input_count:]))

            return run
        root = Path(snapshot(self.build_root, kernel.source_files))
        module = self.load_native(
            root, kernel.source_files, backend, kernel.compile_flags
        )
        return self.entry(module, kernel.symbol)

    def load_python(self, root: Path, kernel: Kernel) -> Callable[..., Any]:
        name = f"_klineage_kernel_{kernel.fingerprint[:MODULE_HASH_LENGTH]}"
        spec = importlib.util.spec_from_file_location(name, root / kernel.source_path)
        if spec is None or spec.loader is None:
            raise ImportError(f"cannot load Python entry {kernel.source_path!r}")
        module = importlib.util.module_from_spec(spec)
        modules = {name: module}
        directory = root / BUNDLE_SOLUTION
        with source_import_scope(directory, modules):
            spec.loader.exec_module(module)
            function = self.entry(module, kernel.symbol)

        # Delayed imports need the same private modules as initial imports.
        def run(*args):
            with source_import_scope(directory, modules):
                return function(*args)

        return run

    @staticmethod
    def entry(module: Any, symbol: str) -> Callable[..., Any]:
        function = getattr(module, symbol)
        if not callable(function):
            raise TypeError(f"bundle entry point {symbol!r} is not callable")
        return function

    def load_native(
        self,
        root: Path,
        source_files: Mapping[str, str],
        backend: Backend,
        compile_flags: Sequence[str] = (),
    ):
        native_files = {
            path: source
            for path, source in source_files.items()
            if path != BUNDLE_CONFIG and Path(path).suffix != ".py"
        }
        sources = [
            path
            for path in sorted(native_files)
            if Path(path).suffix in backend.native_suffixes
        ]
        if not sources:
            raise ValueError(f"{backend.kind} build requires native source files")
        include_paths = [str(root / BUNDLE_SOLUTION), *map(str, self.include_paths)]

        with IMPORT_LOCK:
            options = backend.build_options(compile_flags=compile_flags)
            # Cache complete sources, flags, includes, and architecture together.
            digest = hashlib.sha256(
                json.dumps(
                    [backend.kind, native_files, options, include_paths],
                    sort_keys=True,
                ).encode()
            ).hexdigest()[:MODULE_HASH_LENGTH]
            name = f"klineage_{backend.kind}_{digest}"

    def evaluate(
        self, kernel: Kernel, *, reference: Kernel | None = None
    ) -> ValidationResult:
        try:
            inputs = kernel.problem.values(ValueRole.INPUTS)
            outputs = kernel.problem.values(ValueRole.OUTPUTS)
            if reference is not None:
                require_compatible_contracts(kernel, reference)
            if kernel.function is None or (
                reference is not None and reference.function is None
            ):
                raise ValueError("kernels must be built before evaluation")
        except Exception as error:  # noqa: BLE001 - Record gates; propagate interrupts.
            print(f"Build failed: {error}", file=sys.stderr)
            return ValidationResult(False, False, False)

        try:
            original = require_call_inputs(self.runtime.make_inputs(), len(inputs))
            expected = self.runtime.reference(*clone_inputs(original).args)
            actual = kernel(*clone_inputs(original).args)
            require_output_contract(expected, len(outputs), "reference")
            require_output_contract(actual, len(outputs), "candidate")
            verdict = self.runtime.check_outputs(actual, expected)
            if verdict is not None and not bool(verdict):
                raise ValueError("output checker rejected candidate output")
        except Exception as error:  # noqa: BLE001 - Record gates; propagate interrupts.
            print(f"Correctness failed: {error}", file=sys.stderr)
            return ValidationResult(True, False, False)

        try:
            original = require_call_inputs(self.runtime.make_inputs(), len(inputs))
            timing = self.timer.measure(kernel, args=clone_inputs(original).args)
            timing_evidence(timing.to_dict(), timing.median_ms)
            print("Timing evidence: " + json.dumps(timing.to_dict()), file=sys.stderr)
            reference_latency_ms = None
            passed = True
            if reference is not None:
                baseline = self.timer.measure(
                    reference, args=clone_inputs(original).args
                )
                reference_latency_ms = baseline.median_ms
                passed = verify_performance(timing, baseline)
        except Exception as error:  # noqa: BLE001 - Record gates; propagate interrupts.
            print(f"Timing failed: {error}", file=sys.stderr)
            return ValidationResult(True, True, False)
        return ValidationResult(
            True,
            True,
            passed,
            latency_ms=timing.median_ms,
            reference_latency_ms=reference_latency_ms,
        )


def require_compatible_contracts(candidate: Kernel, reference: Kernel):
    for role in ValueRole:
        if candidate.problem.values(role) != reference.problem.values(role):
            raise ValueError("candidate and reference signatures do not match")

    candidate_problem = candidate.problem
    reference_problem = reference.problem
    if candidate_problem != reference_problem:
        raise ValueError("candidate and reference problem contracts do not match")


def require_call_inputs(value: object, expected_count: int) -> CallInputs:
    if not isinstance(value, CallInputs):
        raise TypeError("ProblemRuntime.make_inputs() must return CallInputs")
    if len(value.args) != expected_count:
        raise ValueError(
            f"ProblemRuntime.make_inputs() returned {len(value.args)} positional "
            f"arguments; ABI declares {expected_count}"
        )
    return value


def require_output_contract(value: object, output_count: int, label: str):
    if output_count == 0 and value is not None:
        raise ValueError(f"{label} must return None for an ABI with no outputs")
    if output_count > 1 and (
        not isinstance(value, tuple) or len(value) != output_count
    ):
        raise ValueError(
            f"{label} must return a {output_count}-item tuple for this ABI"
        )


def clone_inputs(inputs: CallInputs) -> CallInputs:
    return CallInputs(args=tuple(clone_value(value) for value in inputs.args))


def clone_value(value: Any) -> Any:
    torch = sys.modules.get("torch")
    if torch is not None and isinstance(value, torch.Tensor):
        return clone_tensor(value)
    clone = getattr(value, "clone", None)
    if callable(clone):
        try:
            return clone()
        except (TypeError, RuntimeError):
            pass
    if isinstance(value, tuple):
        return tuple(clone_value(item) for item in value)
    if isinstance(value, list):
        return [clone_value(item) for item in value]
    if isinstance(value, dict):
        return {key: clone_value(item) for key, item in value.items()}
    return copy.deepcopy(value)


def clone_tensor(value: torch.Tensor) -> torch.Tensor:
    import torch

    cloned = value.clone()
    if value.layout != torch.strided or cloned.stride() == value.stride():
        return cloned

    # Preserve gaps and overlapping views; plain clone densifies these layouts.
    span = 0
    if value.numel():
        span = 1 + sum(
            (size - 1) * step for size, step in zip(value.shape, value.stride())
        )
    storage = value.as_strided((span,), (1,)).clone()
    return storage.as_strided(value.shape, value.stride())


