    p[4 * u + 1] = pack2(v2, v3);
    p[4 * u + 2] = pack2(v4, v5);
    p[4 * u + 3] = pack2(v6, v7);
  }
  l0 = l0 * a0 + quad_sum(sum0);
  l1 = l1 * a1 + quad_sum(sum1);
